"""Normalise raw settings into a clean config."""
from typing import Any

DEFAULT_LIMITS = {"cpu": 1, "mem": 512}


def normalise(name, *, tags=None, limits=None, region="us-east-1"):
    # None-sentinel: build fresh mutable values inside the body, never in the
    # signature, so no state is shared between calls.
    tags = list(tags) if tags is not None else []
    merged_limits = {**DEFAULT_LIMITS, **(limits or {})}
    return {
        "name": name,
        "tags": sorted(set(tags)),
        "limits": merged_limits,
        "region": region.lower(),
    }

