from normalise import normalise


def test_defaults():
    cfg = normalise("svc")
    assert cfg == {
        "name": "svc",
        "tags": [],
        "limits": {"cpu": 1, "mem": 512},
        "region": "us-east-1",
    }


def test_tags_sorted_and_deduped():
    cfg = normalise("svc", tags=["b", "a", "b"])
    assert cfg["tags"] == ["a", "b"]


def test_limits_merge_over_defaults():
    cfg = normalise("svc", limits={"cpu": 4})
    assert cfg["limits"] == {"cpu": 4, "mem": 512}


def test_region_lowercased():
    assert normalise("svc", region="EU-WEST-1")["region"] == "eu-west-1"

import pytest

from normalise import normalise


def test_stray_positional_raises():
    with pytest.raises(TypeError):
        normalise("svc", "prod")  # would silently be tags if not keyword-only


def test_name_is_accepted_positionally():
    assert normalise("svc")["name"] == "svc"


def test_keyword_form_works():
    cfg = normalise("svc", tags=["x"], region="eu")
    assert cfg["tags"] == ["x"] and cfg["region"] == "eu"

